    M["profile: earnings readable by clients"] = ("profile", T("grant select (lifetime_earnings) on profiles to authenticated;"))
    M["profile: username format not validated"] = ("profile", lambda t: sub(t, "if p_username is not null and p_username !~ '^[a-z0-9_]{3,24}$' then raise exception 'invalid_username'; end if;", ""))
    M["profile: update_my_profile to anon"] = ("profile", A("update_my_profile", "text, text, text, text"))
    M["presence: expired sessions still count online"] = ("profile", lambda t: sub(t, "where ended_at is null and last_seen_at > now() - make_interval(secs => cfg('presence_ttl_seconds')));\nend $$;\n\n-- Presence of one player", "where ended_at is null);\nend $$;\n\n-- Presence of one player"))
    M["presence: heartbeat revives expired sessions"] = ("profile", lambda t: sub(t, "if s.ended_at is not null or s.last_seen_at <= now() - v_ttl then raise exception 'session_expired'; end if;", ""))
    M["presence: heartbeat owner check removed"] = ("profile", lambda t: sub(t, "select * into s from game_sessions where id = p_session and player_id = v_uid for update;\n  if not found then raise exception 'session_not_found'; end if;\n  if s.ended_at is not null or", "select * into s from game_sessions where id = p_session for update;\n  if not found then raise exception 'session_not_found'; end if;\n  if s.ended_at is not null or"))
    M["presence: end_session owner check removed"] = ("profile", lambda t: sub(t, "select * into s from game_sessions where id = p_session and player_id = v_uid for update;\n  if not found then raise exception 'session_not_found'; end if;\n  if s.ended_at is not null then return; end if;", "select * into s from game_sessions where id = p_session for update;\n  if not found then raise exception 'session_not_found'; end if;\n  if s.ended_at is not null then return; end if;"))
    M["presence: live-session cap removed"] = ("profile", lambda t: sub(t, "offset greatest(cfg('session_live_cap')::int - 1, 0));", "offset 1000000);"))
    M["presence: any activity accepted"] = ("profile", lambda t: sub(t, "if p_activity not in ('menu','driving','bus','convoy','idle') then raise exception 'invalid_activity'; end if;", ""))
    M["presence: unknown route accepted"] = ("profile", lambda t: sub(t, "if p_route is not null and not exists (select 1 from world_routes where code = p_route) then raise exception 'unknown_route'; end if;", ""))
    M["presence: sweep_stale_sessions executable by clients"] = ("profile", G("sweep_stale_sessions", ""))
    M["presence: client label not sanitised"] = ("profile", lambda t: sub(t, "select case when p_client ~ '^[A-Za-z0-9_.-]{1,24}$' then p_client else 'unknown' end", "select p_client"))
    M["xp: level window start wrong"] = ("profile", lambda t: sub(t, "(100 * (greatest(p_level, 1) - 1) ^ 2)::bigint", "(50 * (greatest(p_level, 1) - 1) ^ 2)::bigint"))
    # ------------------------------------------------------------------ world state
    M["world: closed route still accepts jobs"] = ("world", lambda t: sub(t, "if r.status = 'OPEN' and p_level >= r.unlock_level then return 'ok'; end if;", "if r.status in ('OPEN','LOCKED') and p_level >= r.unlock_level then return 'ok'; end if;"))
    M["world: route level gate ignored"] = ("world", lambda t: sub(t, "if r.status = 'OPEN' and p_level >= r.unlock_level then return 'ok'; end if;", "if r.status = 'OPEN' then return 'ok'; end if;"))
    M["world: planned routes treated as open"] = ("world", lambda t: sub(t, "select case when p_stored = 'PLANNED' then 'PLANNED'", "select case when false then 'PLANNED'"))
    M["world: level gate missing from effective status"] = ("world", lambda t: sub(t, "when p_level < p_unlock_level then 'LOCKED'", "when false then 'LOCKED'"))
